//! Regression tests for malformed PBF input.
//!
//! Every fixture here is either corrupt or lies about its own structure. The
//! reader has to report those cases as errors (or end the iteration), never by
//! panicking, looping forever, or silently accepting truncated data.
//!
//! The fixtures are generated by `tests/data/generate.py`.

use osmpbf::*;

const UNKNOWN_MEMBER_TYPE: &str = "tests/data/unknown_member_type.osm.pbf";
const NEGATIVE_DATASIZE: &str = "tests/data/negative_datasize.osm.pbf";
const HUGE_HEADER: &str = "tests/data/huge_header.osm.pbf";
const POISONED_READER: &str = "tests/data/poisoned_reader.osm.pbf";
const VALID_FILE: &str = "tests/test.osm.pbf";
const BAD_TAG_INDEX: &str = "tests/data/bad_tag_index.osm.pbf";
const BAD_UTF8: &str = "tests/data/bad_utf8.osm.pbf";
const DENSE_BAD_TAG: &str = "tests/data/dense_bad_tag.osm.pbf";
const DENSE_MISMATCH: &str = "tests/data/dense_mismatch.osm.pbf";
const TRUNCATED_DATASIZE: &str = "tests/data/truncated_datasize.osm.pbf";
const THREE_BYTES: &str = "tests/data/three_bytes.osm.pbf";
const LZ4_BLOB: &str = "tests/data/lz4_blob.osm.pbf";

/// An unknown relation member type must be reported as `Unknown`, not panic.
#[test]
fn unknown_relation_member_type_is_not_a_panic() {
    let reader = ElementReader::from_path(UNKNOWN_MEMBER_TYPE).unwrap();
    let mut members = 0;

    reader
        .for_each(|element| {
            if let Element::Relation(relation) = element {
                for member in relation.members() {
                    assert_eq!(member.member_type, RelMemberType::Unknown(3));
                    assert_eq!(member.member_id, 10);
                    assert_eq!(member.role().unwrap(), "role");
                    members += 1;
                }
            }
        })
        .unwrap();

    assert_eq!(members, 1);
}

/// A negative `datasize` must be an error.
#[test]
fn negative_datasize_is_an_error() {
    let mut reader = BlobReader::from_path(NEGATIVE_DATASIZE).unwrap();
    assert!(reader.next().unwrap().is_ok(), "header blob should parse");
    let err = reader.next().unwrap().unwrap_err();
    assert!(matches!(
        err.kind(),
        ErrorKind::Blob(BlobError::InvalidDataSize { size: -1 })
    ));
}

/// A blob header that claims 64 KiB in an 8-byte file must end the iteration
/// instead of repeating the same error forever.
#[test]
fn reader_stops_after_an_error() {
    let mut reader = BlobReader::from_path(HUGE_HEADER).unwrap();

    // `take` bounds the test: a reader that kept returning the error would
    // collect 4 items and fail the assertion below instead of hanging.
    let items: Vec<_> = reader.by_ref().take(4).collect();

    assert_eq!(items.len(), 1, "iteration must stop after the first error");
    assert!(items[0].is_err());
}

/// A malformed blob must stop the stream reader, and seeking back must make it
/// usable again.
#[test]
fn seek_recovers_from_a_broken_blob() {
    let mut reader = BlobReader::from_path(POISONED_READER).unwrap();

    assert!(reader.next().unwrap().is_ok(), "header blob");
    assert!(reader.next().unwrap().is_ok(), "data blob");
    assert!(reader.next().unwrap().is_err(), "broken blob");
    assert!(reader.next().is_none(), "iteration stopped");

    reader.seek(ByteOffset(0)).unwrap();
    let first_blob = reader.next().unwrap().unwrap();
    assert_eq!(first_blob.offset(), Some(ByteOffset(0)));

    let again = reader.blob_from_offset(ByteOffset(0)).unwrap();
    assert_eq!(again.offset(), Some(ByteOffset(0)));
}

/// A tag whose key index is out of bounds is skipped, and the following tags
/// are still returned.
#[test]
fn bad_tag_index_is_skipped() {
    let reader = ElementReader::from_path(BAD_TAG_INDEX).unwrap();
    let mut nodes = 0;

    reader
        .for_each(|element| {
            if let Element::Node(node) = element {
                assert_eq!(node.tags().collect::<Vec<_>>(), vec![("role", "name")]);
                nodes += 1;
            }
        })
        .unwrap();

    assert_eq!(nodes, 1);
}

/// Malformed tags are skipped, so only an upper bound for the length is known.
#[test]
fn tag_size_hint_is_conservative() {
    let reader = ElementReader::from_path(BAD_TAG_INDEX).unwrap();

    reader
        .for_each(|element| {
            if let Element::Node(node) = element {
                assert_eq!(node.tags().size_hint(), (0, Some(2)));
            }
        })
        .unwrap();
}

/// A tag that is not valid UTF-8 is skipped instead of ending the iteration.
#[test]
fn invalid_utf8_tag_is_skipped() {
    let reader = ElementReader::from_path(BAD_UTF8).unwrap();

    reader
        .for_each(|element| {
            if let Element::Node(node) = element {
                assert_eq!(node.tags().collect::<Vec<_>>(), vec![("role", "name")]);
            }
        })
        .unwrap();
}

/// The same skipping applies to the tags of a dense node.
#[test]
fn dense_bad_tag_is_skipped() {
    let reader = ElementReader::from_path(DENSE_BAD_TAG).unwrap();

    reader
        .for_each(|element| {
            if let Element::DenseNode(node) = element {
                assert_eq!(node.tags().collect::<Vec<_>>(), vec![("role", "name")]);
            }
        })
        .unwrap();
}

/// Parallel arrays of different lengths must not make `len()` lie.
#[test]
fn dense_node_len_matches_yielded() {
    let mut reader = BlobReader::from_path(DENSE_MISMATCH).unwrap();
    reader.next().unwrap().unwrap(); // header blob
    let block = reader.next().unwrap().unwrap().to_primitiveblock().unwrap();

    let mut groups = 0;
    for group in block.groups() {
        // Three ids but only two latitudes: the shorter array ends the
        // iteration, and nothing pretends otherwise.
        assert_eq!(group.dense_nodes().count(), 2);
        groups += 1;
    }

    assert_eq!(groups, 1);
}

/// A blob that claims to be longer than the file is an error, not an accepted
/// and truncated result.
#[test]
fn truncated_blob_is_an_error() {
    let mut reader = BlobReader::from_path(TRUNCATED_DATASIZE).unwrap();
    assert!(reader.next().unwrap().is_ok(), "header blob");
    assert!(reader.next().unwrap().is_err(), "truncated blob");

    let result = ElementReader::from_path(TRUNCATED_DATASIZE).and_then(|r| r.for_each(|_| {}));
    assert!(result.is_err());
}

/// A file that ends in the middle of a length prefix is an error.
#[test]
fn three_byte_file_is_an_error() {
    let mut reader = BlobReader::from_path(THREE_BYTES).unwrap();
    let item = reader.next().expect("trailing bytes must be reported");
    assert!(item.is_err());
}

/// The stricter checks must not reject well-formed files.
#[test]
fn valid_file_still_reads() {
    let mut elements = 0;

    ElementReader::from_path(VALID_FILE)
        .unwrap()
        .for_each(|_| elements += 1)
        .unwrap();

    assert_eq!(elements, 5);
}

/// A blob compressed with a format this crate does not decode must say so,
/// instead of claiming that the blob is empty.
#[test]
fn unsupported_compression_is_reported() {
    let result = ElementReader::from_path(LZ4_BLOB).and_then(|reader| reader.for_each(|_| {}));
    let err = result.expect_err("lz4 blobs are not supported");

    assert!(matches!(
        err.kind(),
        ErrorKind::Blob(BlobError::UnsupportedCompression { kind: "lz4" })
    ));
}

/// Errors must expose their underlying cause through `source()`.
#[test]
fn errors_chain_to_their_cause() {
    let io_err = ElementReader::from_path("tests/data/does-not-exist.osm.pbf")
        .expect_err("opening a missing file fails");
    assert!(std::error::Error::source(&io_err).is_some());

    let mut reader = BlobReader::from_path(POISONED_READER).unwrap();
    reader.next();
    reader.next();
    // Wire-format errors are leaf errors, but they must describe the problem.
    let malformed = reader.next().unwrap().unwrap_err();
    let message = malformed.to_string();
    assert!(
        message.contains("malformed"),
        "unexpected error message: {message}"
    );
}
